315	void StaPipCore::computeClipObjectSpacePlanes(const M4x4& mvp) {
316	  const float nearZ = rendererCore->getSettings().getNear() -
317	                      (-PlanesClipAlgorithm::clipMargin);
318	  const float farZ = -rendererCore->getSettings().getFar();
319	  const float b = VU1_CLIP_XY_BAND;
320	  const float planes[8][5] = {
321	      {0.0F, 0.0F, -1.0F, 0.0F, nearZ},  // near
322	      {0.0F, 0.0F, 1.0F, 0.0F, -farZ},   // far
323	      {-1.0F, 0.0F, 0.0F, b, 0.0F},      // right
324	      {1.0F, 0.0F, 0.0F, b, 0.0F},       // left
325	      {0.0F, -1.0F, 0.0F, b, 0.0F},      // bottom (projection flips Y)
326	      {0.0F, 1.0F, 0.0F, b, 0.0F},       // top
327	      // Modified by TyraX: EE-only, never uploaded. The cull program's clipw
328	      // tests |z| < |w| on top of x and y, so a package may only take that
329	      // path when it is inside the exact near (z <= w) and far (z >= -w)
330	      // planes too. The guard band's own near constant is DELIBERATELY looser
331	      // (PlanesClipAlgorithm::clipMargin), which leaves a thin shell in front
332	      // of the near plane where the clipper draws a triangle the cull program
333	      // would ADC away - a hole at point blank range.
334	      {0.0F, 0.0F, -1.0F, 1.0F, 0.0F},  // exact near
335	      {0.0F, 0.0F, 1.0F, 1.0F, 0.0F},   // exact far
336	  };
337	
338	  const float* m = mvp.data;
339	  for (u8 i = 0; i < 8; ++i) {
340	    const float* p = planes[i];
341	    Plane& out = clipObjectSpacePlanes[i];
342	    out.normal.x = p[0] * m[0] + p[1] * m[1] + p[2] * m[2] + p[3] * m[3];
343	    out.normal.y = p[0] * m[4] + p[1] * m[5] + p[2] * m[6] + p[3] * m[7];
344	    out.normal.z = p[0] * m[8] + p[1] * m[9] + p[2] * m[10] + p[3] * m[11];
345	    out.normal.w = 1.0F;
346	    out.distance = p[4] + p[0] * m[12] + p[1] * m[13] + p[2] * m[14] +
347	                   p[3] * m[15];
348	  }
349	}
350	
351	// Modified by TyraX: guard-band routing (docs/vu1-clipping.md).
352	//
353	// A package is classified against the VIEW frustum (the screen edge), but the
354	// VU1 clip planes are the near/far pair plus an X/Y band at
355	// VU1_CLIP_XY_BAND * w - about seven times the screen's half extent, still
356	// inside the GS raster window. So a package that merely straddles the screen
357	// border crosses no VU clip plane at all, and the packager says so:
358	// `activePlaneMaskAABB` sets a bit when the box crosses OR lies outside a
359	// plane, hence an all-clear over its eight planes means the whole box is
360	// inside every one of them - including w > 0, because for a negative w the
361	// two side half-spaces are contradictory and at least one bit would be set.
362	//
363	// Such a package needs no cutting: every vertex passes the cull program's own
364	// clipw judgement and the GS scissor crops the raster. Sending it to the
365	// clipper anyway cost a 1/3-size split (3x the VU1 kicks), a memcpy of every
366	// vertex stream instead of a DMA by reference, and the clip program's scratch
367	// stores - all to run a plane loop with nothing active.
368	//
369	// The flag is only ever set with VU1 clipping on: with the EE clipper the
370	// packager has no clip planes to test and fills clipPlaneMask with the
371	// VIEW-plane crossing mask for telemetry instead.
372	bool StaPipCore::isGuardBandOnly(const StaPipBagPackage& package) const {
373	  return package.guardBandOnly;
374	}
