376	void StaPipCore::recordPackage(const StaPipBagPackage& package,
377	                               const CoreBBoxFrustum& route) {
378	  if (!telemetryEnabled) return;
379	
380	  // Modified by TyraX: a strip of N vertices is N-2 triangles, not N/3.
381	  const u32 triangles =
382	      package.bag != nullptr && package.bag->stripped
383	          ? (package.size >= 2 ? package.size - 2 : 0)
384	          : package.size / 3;
385	  if (route == IN_FRUSTUM) {
386	    ++telemetry.packagesCull;
387	    telemetry.trianglesCull += triangles;
388	  } else if (route == PARTIALLY_IN_FRUSTUM) {
389	    ++telemetry.packagesClip;
390	    telemetry.trianglesClip += triangles;
391	    u8 bits = package.clipPlaneMask;
392	    u8 count = 0;
393	    while (bits != 0) {
394	      count += bits & 1U;
395	      bits >>= 1;
396	    }
397	    ++telemetry.activePlanePopcount[count <= 6 ? count : 6];
398	  } else {
399	    ++telemetry.packagesOutside;
400	    telemetry.trianglesOutside += triangles;
401	  }
402	}
403	
404	// Modified by TyraX: the subset of packagesCull that took the cull path ONLY
405	// because of the guard band - i.e. what the clipper no longer sees. Recorded
406	// at the routing sites rather than inside recordPackage, so a bag that culls
407	// everything anyway (fullClipChecks off) is not counted.
408	void StaPipCore::recordGuardBandPackage(const StaPipBagPackage& package) {
409	  if (!telemetryEnabled) return;
410	  ++telemetry.packagesGuardBand;
411	  // Modified by TyraX: the SAME rule recordPackage uses, or this counter
412	  // measures a different thing from the `cull` population it documents itself
413	  // as a subset of. It did: over one garage capture guard averaged 21.5
414	  // triangles per package against cull's 37.9, purely because a strip package
415	  // was charged size/3 here and size-2 there.
416	  telemetry.trianglesGuardBand +=
417	      package.bag != nullptr && package.bag->stripped
418	          ? (package.size >= 2 ? package.size - 2 : 0)
419	          : package.size / 3;
420	}
421	
422	void StaPipCore::recordOutsideBag(const StaPipBag* bag) {
423	  if (!telemetryEnabled) return;
424	  // Modified by TyraX: a rejected bag is sliced into the same packages it would
425	  // have been submitted as, and a stripped one gives EACH of those its own
426	  // strip - so the bag is packages * (runLength - 2) triangles, not
427	  // count - 2. Charging the whole bag as one strip over-counted by
428	  // 2 * (packages - 1), which is exactly the population this counter exists to
429	  // compare against the submitted one.
430	  const u32 outsidePackages = (bag->count + maxVertCount - 1) / maxVertCount;
431	  telemetry.packagesOutside += outsidePackages;
432	  if (!bag->stripped) {
433	    telemetry.trianglesOutside += bag->count / 3;
434	  } else {
435	    const u32 whole = bag->count / maxVertCount;
436	    const u32 tail = bag->count - whole * maxVertCount;
437	    telemetry.trianglesOutside +=
438	        whole * (maxVertCount >= 2 ? maxVertCount - 2 : 0) +
439	        (tail >= 2 ? tail - 2 : 0);
440	  }
441	}
