443	u32 StaPipCore::getMaxVertCountByBag(const StaPipBag* bag) {
444	  // Added by TyraX: the two halves of this function are charged separately
445	  // (stapip_attrib.hpp) - resolving the program against doing the arithmetic -
446	  // because they have completely different fixes.
447	  TYRA_ATTRIB_MARK(attribProgStart);
448	  StaPipVU1Program* const cullProgram = qbufferRenderer.getCullProgramByBag(bag);
449	  TYRA_ATTRIB_ADD(bdProgTicks, attribProgStart);
450	
451	  TYRA_ATTRIB_MARK(attribCalcStart);
452	  const u32 derived = cullProgram->getMaxVertCount(
453	      bag->color->many == nullptr, qbufferRenderer.getBufferSize());
454	  TYRA_ATTRIB_ADD(bdSizeCalcTicks, attribCalcStart);
455	
456	  // Modified by TyraX: an explicit package size pins coplanar passes over one
457	  // vertex array to the same package boundaries, so they classify against the
458	  // frustum identically and take the same route (VU1 divide vs EE clipper) -
459	  // see StaPipBag::packageSize. Never above the class's own capacity (that
460	  // overflows the VU1 buffer) and always a multiple of 3, the invariant
461	  // getMaxVertCount itself keeps, so a package holds whole triangles. (It was
462	  // a multiple of 9 until the rounding step was relaxed - see
463	  // StaPipVU1Program::getMaxVertCount for why the second /3 was not load-bearing.)
464	  if (bag->packageSize == 0 || bag->packageSize >= derived) return derived;
465	  const u32 pinned = (bag->packageSize / 3) * 3;
466	  return pinned < 3 ? derived : pinned;
467	}
