477	// Modified by TyraX: experiment (c) - see the header. The stapip_cull_tce_envn
478	// image assumes unit normals and drops the per-vertex rsqrt; this is the EE
479	// half of that bargain, paid once per array rather than once per vertex per
480	// frame. The paint pass reads the same array for its fresnel and is happy
481	// with unit normals too.
482	void StaPipCore::ensureEnvNormalsUnit(StaPipBag* bag) {
483	  Vec4* n = bag->texture->coordinates;
484	  if (n == nullptr || bag->count == 0) return;
485	  const u32 content =
486	      bag->texture->contentVersion ? *bag->texture->contentVersion : 0;
487	  EnvNormalsSeen& e =
488	      envNormalsSeen[(reinterpret_cast<uintptr_t>(n) >> 4) & 31];
489	  if (e.coordinates == n && e.count == bag->count &&
490	      e.bboxVersion == bag->bboxVersion && e.content == content)
491	    return;
492	  for (u32 i = 0; i < bag->count; i++) {
493	    const float l2 = n[i].x * n[i].x + n[i].y * n[i].y + n[i].z * n[i].z;
494	    if (l2 > 1e-12F) {
495	      const float inv = 1.0F / sqrtf(l2);
496	      n[i].x *= inv, n[i].y *= inv, n[i].z *= inv;
497	    }
498	  }
499	  e.coordinates = n, e.count = bag->count, e.bboxVersion = bag->bboxVersion,
500	  e.content = content;
501	  // A handful per boot (once per array), so an A/B arm can prove it ran.
502	  static u32 logged = 0;
503	  if (logged < 4) {
504	    ++logged;
505	    TYRA_LOG("VU1 experiment (c): normalized ", bag->count, " env normals");
506	  }
507	}
