509	void StaPipCore::render(StaPipBag* bag) {
510	  HardwareTrace::Scope traceBag("Static_bag");
511	  TYRA_ATTRIB_MARK(attribRenderStart);
512	  TYRA_ATTRIB_INC(renderCalls);
513	  if (bag->count <= 0) {
514	    TYRA_ATTRIB_ADD(renderTicks, attribRenderStart);
515	    return;
516	  }
517	
518	  // Modified by TyraX: GS hardware fog - the PRIM FGE bit follows the
519	  // renderer-level fog state (see RendererCore::setFog), with a per-bag
520	  // opt-out (sky dome).
521	  prim.fogging = rendererCore->fog.enabled && !bag->info->fogDisabled
522	                     ? DRAW_ENABLE
523	                     : DRAW_DISABLE;
524	
525	  bool frustumCull =
526	      bag->info->frustumCulling == PipelineInfoBagFrustumCulling_Precise;
527	
528	  TYRA_ASSERT(bag->vertices != nullptr,
529	              "Vertices are required in 3D render bag!");
530	  TYRA_ASSERT(bag->info != nullptr, "Info bag is required in 3D render bag!");
531	  TYRA_ASSERT(bag->info->model != nullptr,
532	              "Info bag's model pointer is empty!");
533	  TYRA_ASSERT(bag->color != nullptr, "Color bag is required in 3D render bag!");
534	  TYRA_ASSERT(bag->color->single || bag->color->many,
535	              "At least one color is required in 3D render bag!");
536	  TYRA_ASSERT((!bag->color->many && !bag->lighting) ||
537	                  (bag->color->many && !bag->lighting) ||
538	                  (!bag->color->many && bag->lighting),
539	              "Multicolor is not supported with lighting, please choose one!");
540	  TYRA_ASSERT(
541	      !bag->lighting || (bag->lighting->lightMatrix && bag->lighting->normals &&
542	                         bag->lighting->dirLights),
543	      "If you want lighting, please provide light matrix normals and dir "
544	      "lights!");
545	  // Modified by TyraX: a billboard bag carries a texture bag purely for the
546	  // per-particle params channel - the image itself is optional there.
547	  TYRA_ASSERT(!bag->texture || ((bag->texture->texture || bag->billboard) &&
548	                                bag->texture->coordinates),
549	              "If you want texture, please provide texture and coordinates!");
550	  // Modified by TyraX: particle billboards (centers expanded on VU1).
551	  // frustumCulling None is SAFE here (unlike ordinary bags - see the
552	  // "never submit with None" pitfall): the billboard programs cull every
553	  // quad whose corner leaves the GS raster window / depth range, so
554	  // off-screen centers never wrap the 4096-px window.
555	  TYRA_ASSERT(!bag->billboard ||
556	                  (bag->texture && bag->texture->coordinates &&
