1033	// Inverse of an affine model matrix (rotation * scale + translation).
1034	// M4x4 is column-major: data[0..3] = X basis, [4..7] = Y, [8..11] = Z,
1035	// [12..14] = translation. inv3x3 comes out row-major.
1036	void invertAffine(const float* m, float* inv3x3, float* invT) {
1037	  const float a = m[0], b = m[4], c = m[8];
1038	  const float d = m[1], e = m[5], f = m[9];
1039	  const float g = m[2], h = m[6], i = m[10];
1040	  float det = a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
1041	  if (det > -1e-12F && det < 1e-12F) det = 1e-12F;
1042	  const float id = 1.0F / det;
1043	  inv3x3[0] = (e * i - f * h) * id;
1044	  inv3x3[1] = (c * h - b * i) * id;
1045	  inv3x3[2] = (b * f - c * e) * id;
1046	  inv3x3[3] = (f * g - d * i) * id;
1047	  inv3x3[4] = (a * i - c * g) * id;
1048	  inv3x3[5] = (c * d - a * f) * id;
1049	  inv3x3[6] = (d * h - e * g) * id;
1050	  inv3x3[7] = (b * g - a * h) * id;
1051	  inv3x3[8] = (a * e - b * d) * id;
1052	  invT[0] = -(inv3x3[0] * m[12] + inv3x3[1] * m[13] + inv3x3[2] * m[14]);
1053	  invT[1] = -(inv3x3[3] * m[12] + inv3x3[4] * m[13] + inv3x3[5] * m[14]);
1054	  invT[2] = -(inv3x3[6] * m[12] + inv3x3[7] * m[13] + inv3x3[8] * m[14]);
1055	}
