1057	// Builds the object-space spot light for this mesh: transforms the world
1058	// light through the inverse model matrix, expresses the range in object
1059	// units via the (assumed near-uniform) mesh scale, and precomputes the
1060	// constants the cull VU1 programs and the EE clipper both consume.
1061	StaPipClipperSpot buildSpotForBag(const RendererCoreSpotLight& spot,
1062	                                  const M4x4* model) {
1063	  StaPipClipperSpot out;
1064	  out.enabled = spot.enabled;
1065	  if (!spot.enabled) return out;
1066	
1067	  float inv[9], invT[3];
1068	  invertAffine(model->data, inv, invT);
1069	
1070	  out.position.x = inv[0] * spot.position.x + inv[1] * spot.position.y +
1071	                   inv[2] * spot.position.z + invT[0];
1072	  out.position.y = inv[3] * spot.position.x + inv[4] * spot.position.y +
1073	                   inv[5] * spot.position.z + invT[1];
1074	  out.position.z = inv[6] * spot.position.x + inv[7] * spot.position.y +
1075	                   inv[8] * spot.position.z + invT[2];
1076	  out.position.w = 1.0F;
1077	
1078	  Vec4 dir;
1079	  dir.x = inv[0] * spot.direction.x + inv[1] * spot.direction.y +
1080	          inv[2] * spot.direction.z;
1081	  dir.y = inv[3] * spot.direction.x + inv[4] * spot.direction.y +
1082	          inv[5] * spot.direction.z;
1083	  dir.z = inv[6] * spot.direction.x + inv[7] * spot.direction.y +
1084	          inv[8] * spot.direction.z;
1085	  float dirLen2 = dir.x * dir.x + dir.y * dir.y + dir.z * dir.z;
1086	  if (dirLen2 < 1e-10F) dirLen2 = 1.0F;
1087	
1088	  // A world direction through the inverse scales by 1/s (uniform scale s),
1089	  // so |dir|^2 = 1/s^2 - reuse it to express the range in object units.
1090	  const float objRange2 = spot.range * spot.range * dirLen2;
1091	
1092	  const float invDirLen = 1.0F / Math::sqrtNonNegative(dirLen2);
1093	  out.direction.x = dir.x * invDirLen;
1094	  out.direction.y = dir.y * invDirLen;
1095	  out.direction.z = dir.z * invDirLen;
1096	  out.direction.w = 0.0F;
1097	
1098	  out.color[0] = spot.color.r;
1099	  out.color[1] = spot.color.g;
1100	  out.color[2] = spot.color.b;
1101	  out.invRange2 = 1.0F / objRange2;
1102	
1103	  // Point (omni) light through the SAME spot constants: zero direction makes
1104	  // the axial term t = max(0, d.dir) collapse to 0, so the cone factor
1105	  // becomes (0 - cosCut2*dist2)*invSoft = dist2 * invSoft with cosCut2 = -1.
1106	  // invSoft is sized to saturate that to 1 within ~1% of the range - the
1107	  // radial falloff alone shapes the light. No VU1 change, no micro memory.
1108	  if (spot.point) {
1109	    out.direction.x = 0.0F;
1110	    out.direction.y = 0.0F;
1111	    out.direction.z = 0.0F;
1112	    out.cosCut2 = -1.0F;
1113	    out.invSoft = 1.0e4F / objRange2;
1114	    return out;
1115	  }
1116	
1117	  out.cosCut2 = spot.cosCutoff * spot.cosCutoff;
1118	  // The VU1/EE cone term is clamp01((t^2 - cosCut2*dist2) * invSoft). Its
1119	  // SIGN is the exact angular cutoff and is distance-independent, but its
1120	  // MAGNITUDE scales with dist2 - so sizing invSoft off the full range
1121	  // (objRange2 * (1 - cosCut2)) made the beam ramp up across the whole
1122	  // range: dim on everything close to the lamp, fully bright only near its
1123	  // far end. On the camera flashlight that reads as "it doesn't light what
1124	  // I'm looking at". Saturate at a fraction of the range instead; the
1125	  // cutoff ANGLE is unchanged, the edge just gets crisper.
1126	  constexpr float kFullBrightAt = 0.18F;  // of the range, on the axis
1127	  const float coneBase =
1128	      objRange2 * kFullBrightAt * kFullBrightAt * (1.0F - out.cosCut2);
1129	  out.invSoft = coneBase > 1e-10F ? spot.softness / coneBase : 0.0F;
1130	  return out;
1131	}
