1151	      {0.0F, 0.0F, -1.0F, 0.0F, clipNearZ, 0.0F, 0.0F, 0.0F},
1152	      // far: z >= clipFarZ (exact, matches the EE clipper)
1153	      {0.0F, 0.0F, 1.0F, 0.0F, -clipFarZ, 0.0F, 0.0F, 0.0F},
1154	      // guard band X/Y at +/-VU1_CLIP_XY_BAND * w - strictly inside the
1155	      // GS raster window; the scissor trims the rest of the way
1156	      {-1.0F, 0.0F, 0.0F, VU1_CLIP_XY_BAND, 0.0F, 0.0F, 0.0F, 0.0F},
1157	      {1.0F, 0.0F, 0.0F, VU1_CLIP_XY_BAND, 0.0F, 0.0F, 0.0F, 0.0F},
1158	      {0.0F, -1.0F, 0.0F, VU1_CLIP_XY_BAND, 0.0F, 0.0F, 0.0F, 0.0F},
1159	      {0.0F, 1.0F, 0.0F, VU1_CLIP_XY_BAND, 0.0F, 0.0F, 0.0F, 0.0F},
1160	  };
1161	  packet2_utils_vu_open_unpack(objectDataPacket, VU1_CLIP_PLANES_ADDR, false);
1162	  {
1163	    for (u32 i = 0; i < 6; i++)
1164	      for (u32 j = 0; j < 8; j++)
1165	        packet2_add_float(objectDataPacket, planes[i][j]);
1166	  }
1167	  packet2_utils_vu_close_unpack(objectDataPacket);
