458	void RendererCore::completePipelineFrame() {
459	  if (!pipelineFramePending) return;
460	  pipelineFramePending = false; // waits must not recursively present this job
461	#if TYRA_HARDWARE_TRACE
462	  HardwareTrace::PresentContext traceOwner(
463	      tracePendingEpoch == HardwareTrace::captureEpoch() ? tracePendingJob : 0,
464	      pipelineSequence, pipelineContext);
