466	  HardwareTrace::Scope traceCompletion("PendingPresent", HardwareTrace::Kind::Span, false);
467	  { HardwareTrace::Scope trace("VIF_completion_wait", HardwareTrace::Kind::Wait, false);
468	    Vif1Queue::waitFor(pipelineSequence); }
469	  gs.setRecordingContext(pipelineContext);
470	  // The final FLUSHA/DIRECT FINISH was recorded in this job's sole chain.
471	  // Wait its GS tail, then consume the exclusive event before the next job.
472	  sync.waitAndClear();
