      }
      if (!b.volBack.empty()) {
        b.volBack.bind(b.volClrBag);
        b.volClrBag->count = (u32)b.volBack.size();
        b.volClrBag->bboxVersion = ++g_bboxStamp;
        (NightAblation::submitted(NightAblation::Shadows), NightAblation::extraSubmitted(NightAblation::Pools), stapip.core.render(b.volClrBag.get()));
      }
      rc.alphaMask.end();
    }
  }
}
