2222	  key.sts = bag->texture != nullptr ? bag->texture->coordinates : nullptr;
2223	  key.colors = bag->color->many;
2224	  key.normals = bag->lighting != nullptr ? bag->lighting->normals : nullptr;
2225	  key.program = getCullProgramByBag(bag);
2226	  key.count = bag->count;
