    prim_t spritePrim=*prim; spritePrim.type=PRIM_SPRITE;
    packet2_utils_vu_open_unpack(packet,2+3*buffer->size,true);
    packet2_utils_gs_add_prim_giftag(packet,&spritePrim,buffer->size/3,
